// Sunday report card (TP-2) — the week in one page, computed in code.
//
// "Rules compute, the model talks": every number and every sentence on the
// card is built here. The model writes two sentences over it and PICKS one
// of the pre-validated options by kind — it never composes a proposal. The
// Sunday job (functions/report-card-request.js), the page (recompute on
// open) and the eval all call these functions.
//
// Pure. Imports only mirrored siblings.
//
// MIRRORED: functions/report-card.js is generated by
//   node scripts/sync-mirror.mjs js/core/features/report-card.js functions/report-card.js
// (tests/unit/movement-patterns-mirror.test.js enforces parity).

const { buildScoreboard } = require('./progress-scoreboard');
const { checkDeloadNeeded, readinessState, RULE_THRESHOLDS } = require('./training-rules');
const { weightIncrement, buildExerciseSessions, stallState } = require('./progression');
const { deriveProgramWeek, isDeloadTarget } = require('./week-targets');
const { getSessionIntent, weekOverrideOf } = require('./session-intent');
const { inferRole } = require('./movement-patterns');
const { rankRotationCandidates } = require('./exercise-rotation');
const { weekKindLabel, describeStrengthChange, describeStuck, pctChange, findJargon } = require('./plain-language');
const { goalsWithStatus, shortDate, weeksUntil } = require('./goal-progress');
const { weightAverage, scanLeanMass, scanBodyFatPct, scansAsOf, shiftDate } = require('./body-stats');

const DEFAULT_TIME_ZONE = 'America/Chicago';
const REPORT_CARD_VERSION = 1;
const OPTION_KINDS = ['stay', 'lighter-week', 'swap', 'peak'];
const GRADE_LABELS = { good: 'Good week', solid: 'Solid week', rough: 'Rough week' };
const DAY_NAMES = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
const NUMBER_WORDS = ['zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine', 'ten'];
const round1 = (n) => Math.round(n * 10) / 10;
const words = (n) => (n >= 0 && n <= 10 ? NUMBER_WORDS[n] : String(n));

// ── The week ────────────────────────────────────────────────────────

/** YYYY-MM-DD of `now` in `timeZone` (not UTC — a Sunday-evening run in Chicago is Monday in UTC). */
function localDate(now = new Date(), timeZone = DEFAULT_TIME_ZONE) {
    try {
        return new Intl.DateTimeFormat('en-CA', { timeZone, year: 'numeric', month: '2-digit', day: '2-digit' }).format(now);
    } catch {
        return new Intl.DateTimeFormat('en-CA', { timeZone: DEFAULT_TIME_ZONE, year: 'numeric', month: '2-digit', day: '2-digit' }).format(now);
    }
}

/** 0 = Monday … 6 = Sunday, for a YYYY-MM-DD. */
function dayIndex(dateStr) {
    return (new Date(`${dateStr}T12:00:00Z`).getUTCDay() + 6) % 7;
}

/**
 * The week a card covers: the local Monday–Sunday containing `now`, keyed by
 * its Monday. On a Monday it's the week that just ended (last night's card).
 * @returns {{weekKey: string, from: string, to: string, today: string}}
 */
function reportWeek(now = new Date(), timeZone = DEFAULT_TIME_ZONE) {
    const today = localDate(now, timeZone);
    const dow = dayIndex(today);
    let monday = shiftDate(today, -dow);
    if (dow === 0) monday = shiftDate(monday, -7);
    return { weekKey: monday, from: monday, to: shiftDate(monday, 6), today };
}

// ── Sections ────────────────────────────────────────────────────────

const usable = (w) => w?.date && w.completedAt && !w.cancelledAt;

function plannedDays(weekPlan, settings) {
    const days = weekPlan?.days ? Object.values(weekPlan.days).filter(v => v && v !== 'rest').length : 0;
    if (days) return days;
    const goal = Number(settings?.weeklyGoal);
    return Number.isFinite(goal) && goal > 0 ? goal : null;
}

function distinctDays(workouts, from, to) {
    return new Set(workouts.filter(w => w.date >= from && w.date <= to).map(w => w.date)).size;
}

function showedUpSection(done, week, weekPlan, settings) {
    const planned = plannedDays(weekPlan, settings);
    const inWeek = done.filter(w => w.date >= week.from && w.date <= week.to).sort((a, b) => a.date.localeCompare(b.date));
    const byDate = new Map();
    for (const w of inWeek) if (!byDate.has(w.date)) byDate.set(w.date, w.workoutType || w.templateName || 'Workout');
    const days = [...byDate.entries()].map(([date, name]) => ({ date, day: DAY_NAMES[dayIndex(date)], name }));
    const count = days.length;
    const bar = planned || 1;
    let streakWeeks = 0;
    for (let k = 0; k < 52; k++) {
        const f = shiftDate(week.from, -7 * k);
        if (distinctDays(done, f, shiftDate(f, 6)) >= bar) streakWeeks++;
        else break;
    }
    let sentence;
    if (planned) {
        sentence = `You showed up ${count} of ${planned} day${planned === 1 ? '' : 's'}`;
        sentence += streakWeeks >= 2 ? ` — ${words(streakWeeks)} weeks running.` : '.';
    } else {
        sentence = count ? `You trained ${count} day${count === 1 ? '' : 's'} this week.` : 'No workouts this week.';
    }
    return { planned, done: count, missed: planned ? Math.max(0, planned - count) : 0, days, streakWeeks, sentence };
}

function strengthSection(sb, unit) {
    const rows = sb.primaries.map((p) => {
        const repBest = p.repPR ? `${p.repPR.weight}×${p.repPR.reps}` : null;
        const stuck = p.rung > 0 ? describeStuck({ rung: p.rung }) : null;
        let sentence;
        if (p.trend === 'idle') sentence = `${p.name}: not trained in the last 4 weeks`;
        else if (p.e1rmNow == null) sentence = `${p.name}: no sets to estimate from yet`;
        else sentence = describeStrengthChange({ name: p.name, machine: p.equipment || null, now: p.e1rmNow, prev: p.e1rmPrev, unit, since: 'the 4 weeks before' });
        if (repBest) sentence += ` · new rep best ${repBest}`;
        if (stuck) sentence += ` · ${stuck}`;
        return {
            name: p.name, machine: p.equipment || null, estMaxNow: p.e1rmNow ?? null, estMaxPrev: p.e1rmPrev ?? null,
            deltaPct: pctChange(p.e1rmNow, p.e1rmPrev), trend: p.trend, repBest, stuck, effortRising: !!p.fatigue, sentence,
        };
    });
    return rows;
}

function bodySection(measurements, dexa, asOf, unit) {
    const now = weightAverage(measurements, { asOf, unit });
    const prev = weightAverage(measurements, { asOf: shiftDate(asOf, -28), unit });
    const delta = now && prev ? round1(now.value - prev.value) : null;
    const scans = scansAsOf(dexa, asOf);
    const scan = scans[0] || null;
    const before = scans[1] || null;
    let lastScan = null;
    if (scan) {
        const lean = scanLeanMass(scan, unit);
        const fat = scanBodyFatPct(scan);
        lastScan = {
            date: scan.date, leanMass: lean, bodyFatPct: fat,
            leanDelta: before && lean != null && scanLeanMass(before, unit) != null ? round1(lean - scanLeanMass(before, unit)) : null,
            fatDelta: before && fat != null && scanBodyFatPct(before) != null ? round1(fat - scanBodyFatPct(before)) : null,
        };
    }
    const parts = [];
    if (now) {
        parts.push(`${now.value} ${unit} (7-day average)${delta == null ? '' : delta === 0 ? ', the same as a month ago' : `, ${delta > 0 ? 'up' : 'down'} ${Math.abs(delta)} ${unit} vs a month ago`}`);
    }
    if (lastScan) {
        const lean = lastScan.leanMass == null ? '' : `lean mass ${lastScan.leanMass} ${unit}${lastScan.leanDelta == null ? '' : ` (${lastScan.leanDelta > 0 ? '+' : ''}${lastScan.leanDelta})`}`;
        const fat = lastScan.bodyFatPct == null ? '' : `body fat ${lastScan.bodyFatPct}%${lastScan.fatDelta == null ? '' : ` (${lastScan.fatDelta > 0 ? '+' : ''}${lastScan.fatDelta})`}`;
        parts.push(`Last scan ${shortDate(lastScan.date)}: ${[lean, fat].filter(Boolean).join(' · ')}`);
    }
    return {
        weightAvg7: now ? now.value : null, weightPrev4w: prev ? prev.value : null, delta, lastScan,
        sentence: parts.length ? `${parts.join('. ')}.` : 'No weigh-ins this month — log one and this fills in.',
    };
}

function recoverySection(deload, readiness) {
    const creeping = (deload.fatigue || []);
    const parts = [];
    if (creeping.length) {
        const names = creeping.slice(0, 2).map(f => f.exercise).join(' and ');
        parts.push(`Effort is creeping on ${names}${creeping[0].reason ? ` (${creeping[0].reason})` : ''}.`);
    } else {
        parts.push('Effort is steady on your main lifts.');
    }
    if (readiness?.readinessLow) parts.push(`Readiness has been low — ${readiness.low} of ${readiness.of} check-ins at 2 or under.`);
    else if (readiness?.of) parts.push('Readiness is fine.');
    if (deload.needed && deload.source !== 'fatigue') parts.push(`That's ${words(deload.consecutiveHardWeeks)} hard weeks in a row.`);
    return {
        effortCreeping: creeping.map(f => f.exercise), readinessLow: !!readiness?.readinessLow,
        lighterWeekDue: !!deload.needed, hardWeeks: deload.consecutiveHardWeeks || 0, sentence: parts.join(' '),
    };
}

function balanceSection(sb) {
    const rows = sb.patterns.map(p => ({ pattern: p.pattern, label: p.label, sets: p.setsThisWeek, status: p.status, weeksUnder: p.weeksUnder || 0 }));
    const under = rows.filter(r => r.status === 'under');
    const over = rows.filter(r => r.status === 'over');
    const parts = [];
    for (const r of under.slice(0, 2)) parts.push(`${r.label} ${r.sets} set${r.sets === 1 ? '' : 's'} this week — under what it needs${r.weeksUnder >= 2 ? ', second week running' : ''}.`);
    for (const r of over.slice(0, 1)) parts.push(`${r.label} ${r.sets} sets — more than it can use.`);
    if (!parts.length) parts.push(rows.some(r => r.status === 'recovery') ? 'A lighter week — sets are meant to be low.' : 'Every movement got its sets.');
    return { rows, sentence: parts.join(' ') };
}

function upcomingSection({ program, settings, events, week, asOf }) {
    const nextMonday = shiftDate(week.to, 1);
    const override = weekOverrideOf(settings);
    const intent = getSessionIntent({ program, today: nextMonday, manualDeload: override });
    let nextWeekKind = 'Build week';
    let programWeek = null;
    if (program?.startDate) programWeek = deriveProgramWeek(program, nextMonday);
    if (intent.mode === 'deload') nextWeekKind = 'Lighter week';
    else if (programWeek && !programWeek.finished && programWeek.target) nextWeekKind = weekKindLabel(programWeek.target);
    // The next lighter week the program has scheduled (12 weeks out at most).
    let lighterStarts = intent.mode === 'deload' ? nextMonday : null;
    if (!lighterStarts && program?.startDate) {
        for (let k = 1; k <= 12; k++) {
            const d = shiftDate(nextMonday, 7 * k);
            const pw = deriveProgramWeek(program, d);
            if (pw.finished) break;
            if (pw.target && isDeloadTarget(pw.target)) { lighterStarts = d; break; }
        }
    }
    const thisWeek = program?.startDate ? deriveProgramWeek(program, week.to) : null;
    const waveEndsThisWeek = !!(thisWeek && !thisWeek.finished && programWeek?.finished);
    const nothingSet = !program?.startDate || !!programWeek?.finished;
    const next = (events || []).filter(e => e?.date && e.date > asOf).sort((a, b) => a.date.localeCompare(b.date))[0] || null;
    const event = next ? { id: next.id || null, name: next.name, date: next.date, weeks: weeksUntil(next.date, asOf), peakWeeks: next.peakWeeks ?? 2, lighterBefore: next.lighterBefore !== false } : null;
    const parts = [`Next week: ${nextWeekKind}`];
    if (lighterStarts && lighterStarts !== nextMonday) parts.push(`lighter week starts ${shortDate(lighterStarts)}`);
    if (event) parts.push(`${event.name} in ${event.weeks} week${event.weeks === 1 ? '' : 's'}`);
    let sentence = `${parts.join(' · ')}.`;
    if (waveEndsThisWeek) sentence += " Your plan's weeks end here — set up the next few with the coach.";
    return { nextMonday, nextWeekKind, lighterStarts, event, waveEndsThisWeek, nothingSet, sentence };
}

/** The accessory that's been stuck longest (rung 3 = time to rotate), with the engine's replacement. */
function swapCandidateOf({ done, templates, weekPlan, unit, rotation }) {
    if (!rotation?.lookup) return null;
    const ids = new Set(Object.values(weekPlan?.days || {}).filter(v => v && v !== 'rest'));
    const pool = (templates || []).filter(t => !t.archived && !t.isHidden && Array.isArray(t.exercises) && (!ids.size || ids.has(t.id)));
    let best = null;
    for (const t of pool) {
        t.exercises.forEach((ex, index) => {
            const name = ex?.machine || ex?.name;
            if (!name || inferRole(ex, index) === 'primary') return;
            const st = stallState(buildExerciseSessions(done, name, unit, { machine: ex.equipment ? { name: ex.equipment, id: ex.equipmentId || null } : null }));
            if (st.rung < 3) return;
            if (!best || st.run > best.run) best = { t, index, name, run: st.run };
        });
    }
    if (!best) return null;
    const exclude = best.t.exercises.map(e => e?.machine || e?.name).filter(Boolean);
    const ranked = rankRotationCandidates({ exercise: best.name, equipment: rotation.equipment || [], location: rotation.location || null, lookup: rotation.lookup, exclude, limit: 1 });
    const c = ranked.candidates[0];
    if (!c) return null;
    return {
        templateId: best.t.id, templateName: best.t.name || null, index: best.index,
        from: best.name, to: c.name, equipment: c.equipment,
        reason: `stuck for ${best.run} sessions; ${c.reason}`,
    };
}

function optionsOf({ recovery, upcoming, swap }) {
    const out = [{ kind: 'stay', label: 'Keep going as planned' }];
    const nextLighter = upcoming.nextWeekKind === 'Lighter week';
    const why = recovery.lighterWeekDue
        ? (recovery.hardWeeks >= 3 && !recovery.effortCreeping.length ? `${recovery.hardWeeks} hard weeks in a row` : 'effort is climbing on your main lifts')
        : recovery.readinessLow ? 'readiness has been low' : recovery.effortCreeping.length >= 2 ? 'effort is creeping on two main lifts' : null;
    if (why && !nextLighter) {
        out.push({
            kind: 'lighter-week', label: 'Make next week lighter',
            payload: { from: upcoming.nextMonday, weeks: 1, weightPct: recovery.lighterWeekDue && !recovery.effortCreeping.length ? -35 : -10, label: 'Lighter week', reason: why },
        });
    }
    if (swap) out.push({ kind: 'swap', label: `Rotate ${swap.from}`, payload: swap });
    const ev = upcoming.event;
    if (ev && ev.lighterBefore && !nextLighter) {
        const eventMonday = shiftDate(ev.date, -dayIndex(ev.date));
        const lighterMonday = shiftDate(eventMonday, -7 * ((ev.peakWeeks || 0) + 1));
        if (lighterMonday === upcoming.nextMonday) {
            out.push({
                kind: 'peak', label: `Take the lighter week before ${ev.name}`,
                payload: { from: upcoming.nextMonday, weeks: 1, weightPct: -35, label: `Lighter week before ${ev.name}`, reason: `${ev.name} is ${ev.weeks} weeks out`, eventId: ev.id },
            });
        }
    }
    return out;
}

function gradeOf(showedUp, goals) {
    const adherence = showedUp.planned ? showedUp.done / showedUp.planned : null;
    const behind = goals.filter(g => g.status === 'behind').length;
    if ((adherence != null && adherence < 0.5) || behind >= 2 || showedUp.done === 0) return 'rough';
    if ((adherence == null || adherence >= 0.8) && behind === 0) return 'good';
    return 'solid';
}

function headlineOf(showedUp, strength) {
    const s1 = showedUp.sentence;
    const moving = strength.filter(r => r.trend === 'up').length;
    const tracked = strength.filter(r => r.estMaxNow != null).length;
    if (!tracked) return s1;
    const watch = strength.find(r => r.stuck) || strength.find(r => r.trend === 'down');
    let s2 = moving
        ? `Strength is moving on ${words(moving)} of ${words(tracked)} main lift${tracked === 1 ? '' : 's'}`
        : `Strength is holding on your ${words(tracked)} main lift${tracked === 1 ? '' : 's'}`;
    if (watch) s2 += `; ${watch.name} is the one to watch`;
    return `${s1} ${s2}.`;
}

/**
 * @param {object} args
 * @param {{weekKey, from, to}} args.week - from reportWeek()
 * @param {string} args.today - local YYYY-MM-DD (≤ week.to on a mid-week build)
 * @param {{equipment: Array, location: string|null, lookup: Function}} [args.rotation] - enables the swap option
 */
function buildReportCard({
    workouts = [], templates = [], weekPlan = null, program = null, measurements = [], dexa = [],
    goals = [], events = [], settings = {}, unit = 'lbs', week, today = null, rotation = null, builtAt = null,
} = {}) {
    const u = unit === 'kg' ? 'kg' : 'lbs';
    const asOf = today && today < week.to ? today : week.to;
    const done = (workouts || []).filter(usable).filter(w => w.date <= asOf);
    const plates = u === 'kg' ? settings?.plateKg : settings?.plateLbs;
    const inc = weightIncrement(u, plates);
    const sb = buildScoreboard({ workouts: done, templates, unit: u, today: asOf, config: { increment: inc } });

    const showedUp = showedUpSection(done, week, weekPlan, settings);
    const strength = strengthSection(sb, u);
    const body = bodySection(measurements, dexa, asOf, u);
    const goalRows = goalsWithStatus((goals || []).filter(g => g.status === 'active' || g.status === 'paused'), {
        workouts: done, templates, measurements, dexa, today: asOf, plates, events,
    }).map(r => ({ id: r.goal.id || null, status: r.status, sentence: r.sentence }));
    const deload = checkDeloadNeeded(done, RULE_THRESHOLDS, { today: asOf, unit: u, inc, primaries: sb.primaries.map(p => p.name) }) || {};
    const recovery = recoverySection(deload, readinessState(done, { today: asOf }));
    const balance = balanceSection(sb);
    const upcoming = upcomingSection({ program, settings, events, week, asOf });
    const swap = swapCandidateOf({ done, templates, weekPlan, unit: u, rotation });
    const options = optionsOf({ recovery, upcoming, swap });
    const grade = gradeOf(showedUp, goalRows);
    return {
        version: REPORT_CARD_VERSION,
        weekKey: week.weekKey, from: week.from, to: week.to, asOf, unit: u, builtAt,
        headline: headlineOf(showedUp, strength),
        grade, gradeLabel: GRADE_LABELS[grade],
        showedUp, strength, body, goals: goalRows, recovery, balance, upcoming, options,
    };
}

// ── The model's two sentences and one choice ────────────────────────

/** The card as the model sees it: sentences and numbers, no payload internals. */
function cardForModel(card) {
    return {
        week: `${shortDate(card.from)} – ${shortDate(card.to)}`,
        grade: card.gradeLabel,
        headline: card.headline,
        showedUp: card.showedUp.sentence,
        strength: card.strength.map(r => r.sentence),
        body: card.body.sentence,
        goals: card.goals.map(g => g.sentence),
        recovery: card.recovery.sentence,
        balance: card.balance.sentence,
        nextWeek: card.upcoming.sentence,
        options: card.options.map(o => ({ kind: o.kind, label: o.label, ...(o.payload?.reason ? { reason: o.payload.reason } : {}) })),
    };
}

/** Does an option still exist on a (recomputed) card? Same kind, and a swap must be the same swap. */
function optionStillValid(chosen, card) {
    if (!chosen?.kind) return false;
    return (card?.options || []).some(o => o.kind === chosen.kind
        && (o.kind !== 'swap' || (o.payload?.from === chosen.payload?.from && o.payload?.to === chosen.payload?.to)));
}

/**
 * Parse the model's reply: {"headline": "...", "choice": "<kind>", "why": "..."}.
 * An unknown choice or an unparseable reply falls back to the card's own
 * headline and "stay" — the card is complete without the model.
 * @returns {{narrative: string, chosen: object, why: string, fallback: string|null}}
 */
function parseReportCardReply(text, card) {
    const stay = card.options.find(o => o.kind === 'stay');
    const m = String(text || '').match(/\{[\s\S]*\}/);
    let j = null;
    try { j = m ? JSON.parse(m[0]) : null; } catch { j = null; }
    if (!j || typeof j.headline !== 'string' || !j.headline.trim()) {
        return { narrative: card.headline, chosen: stay, why: '', fallback: 'unparsed' };
    }
    const narrative = j.headline.trim().slice(0, 400);
    const option = card.options.find(o => o.kind === j.choice);
    const why = typeof j.why === 'string' ? j.why.trim().slice(0, 240) : '';
    if (!option) return { narrative, chosen: stay, why: '', fallback: `unknown choice ${JSON.stringify(j.choice)}` };
    return { narrative, chosen: option, why, fallback: null };
}

/** Every number in a text (for the eval's numbers-match-card check). */
function numbersIn(text) {
    return (String(text || '').match(/\d+(?:\.\d+)?/g) || []).map(Number);
}

/** The numbers the model was shown (cardForModel) — anything else in its text was invented. */
function cardNumbers(card) {
    return new Set(numbersIn(JSON.stringify(cardForModel(card))));
}

/** Jargon anywhere on the card's own sentences (tests keep this at zero). */
function cardJargon(card) {
    const m = cardForModel(card);
    return findJargon([m.headline, m.showedUp, ...m.strength, m.body, ...m.goals, m.recovery, m.balance, m.nextWeek, ...m.options.map(o => `${o.label} ${o.reason || ''}`)].join('\n'));
}

module.exports = { DEFAULT_TIME_ZONE, REPORT_CARD_VERSION, OPTION_KINDS, GRADE_LABELS, localDate, dayIndex, reportWeek, buildReportCard, cardForModel, optionStillValid, parseReportCardReply, numbersIn, cardNumbers, cardJargon };
